        ).use { cursor ->
            if (cursor.count <= 0) {
                return null
            }
            val resultMap = Arguments.createMap()
            cursor.moveToFirst()
            resultMap.mapCursor(cursor)
            return resultMap
        }
    } catch (e: Exception) {
        e.printStackTrace()
        return null
    }
}

fun findByColumns(db: WMDatabase, tableName: String, columnNames: Array<String>, values: QueryArgs): ReadableMap? {
