        db.rawQuery(
                "SELECT * FROM $tableName WHERE $whereString LIMIT 1",
                values
        ).use { cursor ->
            if (cursor.count <= 0) {
                return null
            }
            val resultMap = Arguments.createMap()
            cursor.moveToFirst()
            resultMap.mapCursor(cursor)
            return resultMap
        }
    } catch (e: Exception) {
