        val storeEarliest = minOf(earliest, existingRecord.getDouble("earliest"))
        val storeLatest = maxOf(latest, existingRecord.getDouble("latest"))
        val query = "UPDATE TeamThreadsSync SET earliest=?, latest=? WHERE id=?"
