        if (!myTeamExists) {
            myTeam = fetch(serverUrl, "/api/v4/teams/$teamId/members/me")
        }

        Pair(team, myTeam)
    } catch (e: Exception) {
        e.printStackTrace()
        Pair(null, null)
    }
